1	package shadow
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"io/fs"
8		"os"
9		"path/filepath"
10		"sync"
11		"time"
12	)
13	
14	const storeFileName = "shadow-store.json"
15	const storeFormat = 1
16	
17	// View 是设备影子当前状态的只读快照。
18	type View struct {
19		DeviceID string
20		// Version 是设备当前版本（登记时的初始版本，随有效上报更新）。
21		Version string
22		// Online 表示设备是否在线。新登记设备离线，有效上报置为在线。
23		Online bool
24		// Revision 是当前期望配置的修订号，从零开始，每次成功修改加一。
25		Revision uint64
26		// Desired 是期望配置的完整 JSON 对象。
27		Desired json.RawMessage
28		// Reported 是上报配置的完整 JSON 对象。
29		Reported json.RawMessage
30		// LastSeq 是最后接受的上报序号。
31		LastSeq uint64
32	}
33	
34	// AuditRecord 是一次成功修改期望配置的审计记录。
35	type AuditRecord struct {
36		DeviceID string
37		Operator string
38		Time     time.Time
39		// Revision 是本次修改产生的新修订号。
40		Revision uint64
41		// Before 是修改前的完整期望配置。
42		Before json.RawMessage
43		// After 是修改后的完整期望配置。
44		After json.RawMessage
45	}
46	
47	// deviceState 是单台设备的内部状态。
48	type deviceState struct {
49		Version        string
50		Online         bool
51		Revision       uint64
52		Desired        json.RawMessage
53		Reported       json.RawMessage
54		LastSeq        uint64
55		LastReportTime time.Time
56		// DiffSince 记录每条差异路径首次出现的时间。
57		DiffSince map[string]time.Time
58		Audit     []AuditRecord
59	}
60	
61	// refreshDiff 重新计算差异路径：已有路径保留原时间，新路径使用 t，消失的路径移除。
62	func (d *deviceState) refreshDiff(t time.Time) {
63		entries := computeDiff(d.Desired, d.Reported)
64		next := make(map[string]time.Time, len(entries))
65		for _, e := range entries {
66			if since, ok := d.DiffSince[e.Path]; ok {
67				next[e.Path] = since
68			} else {
69				next[e.Path] = t
70			}
71		}
72		d.DiffSince = next
73	}
74	
75	// Store 是本地设备影子存储，所有状态与审计记录保存在指定目录。
76	// Store 可安全并发使用。
77	type Store struct {
78		mu        sync.Mutex
79		dir       string
80		closed    bool
81		devices   map[string]*deviceState
82		versions  map[string]*versionState
83		campaigns map[string]*campaignState
84	}
85	
86	// Open 打开（必要时创建）位于 dir 的本地影子存储。
87	// 已有内容损坏或格式不识别时返回 ErrCorruptStorage，不会按空数据覆盖。
88	func Open(dir string) (*Store, error) {
89		if err := os.MkdirAll(dir, 0o755); err != nil {
90			return nil, fmt.Errorf("shadow: create store dir: %w", err)
91		}
92		s := &Store{
93			dir:       dir,
94			devices:   map[string]*deviceState{},
95			versions:  map[string]*versionState{},
96			campaigns: map[string]*campaignState{},
97		}
98		data, err := os.ReadFile(s.filePath())
99		if errors.Is(err, fs.ErrNotExist) {
100			return s, nil
101		}
102		if err != nil {
103			return nil, fmt.Errorf("shadow: read store: %w", err)
104		}
105		if err := s.restore(data); err != nil {
106			return nil, err
107		}
108		return s, nil
109	}
110	
111	// Close 关闭存储。关闭后的操作返回 ErrClosed。
112	func (s *Store) Close() error {
113		s.mu.Lock()
114		defer s.mu.Unlock()
115		if s.closed {
116			return ErrClosed
117		}
118		s.closed = true
119		return nil
120	}
121	
122	// Register 登记一台模拟设备。设备标识和初始版本不能为空；
123	// 重复登记返回 ErrDeviceExists。新设备初始离线，双方配置均为空对象。
124	func (s *Store) Register(deviceID, version string) error {
125		s.mu.Lock()
126		defer s.mu.Unlock()
127		if err := s.checkOpen(); err != nil {
128			return err
129		}
130		if deviceID == "" {
131			return ErrInvalidDeviceID
132		}
133		if version == "" {
134			return ErrInvalidVersion
135		}
136		if _, ok := s.devices[deviceID]; ok {
137			return fmt.Errorf("%w: %s", ErrDeviceExists, deviceID)
138		}
139		return s.commit(func() error {
140			s.devices[deviceID] = &deviceState{
141				Version:   version,
142				Desired:   json.RawMessage(`{}`),
143				Reported:  json.RawMessage(`{}`),
144				DiffSince: map[string]time.Time{},
145			}
146			return nil
147		})
148	}
149	
150	// UpdateDesired 修改设备的期望配置，完整替换旧配置。
151	// 需携带操作者、操作时间和已读取的期望修订号；修订号不等于当前值时
152	// 返回 ErrRevisionConflict，影子和审计均不改变。成功时返回新修订号。
153	func (s *Store) UpdateDesired(deviceID, operator string, at time.Time, revision uint64, config json.RawMessage) (uint64, error) {
154		s.mu.Lock()
155		defer s.mu.Unlock()
156		if err := s.checkOpen(); err != nil {
157			return 0, err
158		}
159		d, err := s.lookup(deviceID)
160		if err != nil {
161			return 0, err
162		}
163		if operator == "" {
164			return 0, ErrInvalidOperator
165		}
166		if at.IsZero() {
167			return 0, ErrInvalidTime
168		}
169		cfg, err := validateConfig(config)
170		if err != nil {
171			return 0, err
172		}
173		if revision != d.Revision {
174			return 0, fmt.Errorf("%w: want %d, got %d", ErrRevisionConflict, d.Revision, revision)
175		}
176		var newRevision uint64
177		err = s.commit(func() error {
178			before := d.Desired
179			d.Desired = cfg
180			d.Revision++
181			newRevision = d.Revision
182			d.Audit = append(d.Audit, AuditRecord{
183				DeviceID: deviceID,
184				Operator: operator,
185				Time:     at,
186				Revision: newRevision,
187				Before:   cloneRaw(before),
188				After:    cloneRaw(cfg),
189			})
190			d.refreshDiff(at)
191			return nil
192		})
193		if err != nil {
194			return 0, err
195		}
196		return newRevision, nil
197	}
198	
199	// Report 处理设备上报。需携带正整数序号、时间、非空当前版本和完整配置。
200	// 更大序号更新上报并标为在线；相同序号且版本、配置、时间相同视为重复，
201	// 成功返回但不改变状态；相同序号内容不同或更小序号返回错误。
202	func (s *Store) Report(deviceID string, seq uint64, at time.Time, version string, config json.RawMessage) error {
203		s.mu.Lock()
204		defer s.mu.Unlock()
205		if err := s.checkOpen(); err != nil {
206			return err
207		}
208		d, err := s.lookup(deviceID)
209		if err != nil {
210			return err
211		}
212		if seq == 0 {
213			return ErrInvalidSequence
214		}
215		if at.IsZero() {
216			return ErrInvalidTime
217		}
218		if version == "" {
219			return ErrInvalidVersion
220		}
221		cfg, err := validateConfig(config)
222		if err != nil {
223			return err
224		}
225		switch {
226		case seq < d.LastSeq:
227			return fmt.Errorf("%w: last accepted %d, got %d", ErrStaleSequence, d.LastSeq, seq)
228		case seq == d.LastSeq:
229			if version == d.Version && at.Equal(d.LastReportTime) && rawEqual(cfg, d.Reported) {
230				return nil // 重复上报：成功返回，不改变状态
231			}
232			return fmt.Errorf("%w: sequence %d", ErrReportConflict, seq)
233		}
234		return s.commit(func() error {
235			d.Reported = cfg
236			d.Version = version
237			d.Online = true
238			d.LastSeq = seq
239			d.LastReportTime = at
240			d.refreshDiff(at)
241			return nil
242		})
243	}
244	
245	// SetOffline 将设备标为离线。只改变在线状态，保留版本及双方配置。
246	func (s *Store) SetOffline(deviceID string) error {
247		s.mu.Lock()
248		defer s.mu.Unlock()
249		if err := s.checkOpen(); err != nil {
250			return err
251		}
252		d, err := s.lookup(deviceID)
253		if err != nil {
254			return err
255		}
256		return s.commit(func() error {
257			d.Online = false
258			return nil
259		})
260	}
261	
262	// Get 返回设备影子当前状态的快照。返回的数据是独立副本，
263	// 调用方修改不影响已保存的记录。
264	func (s *Store) Get(deviceID string) (View, error) {
265		s.mu.Lock()
266		defer s.mu.Unlock()
267		if err := s.checkOpen(); err != nil {
268			return View{}, err
269		}
270		d, err := s.lookup(deviceID)
271		if err != nil {
272			return View{}, err
273		}
274		return View{
275			DeviceID: deviceID,
276			Version:  d.Version,
277			Online:   d.Online,
278			Revision: d.Revision,
279			Desired:  cloneRaw(d.Desired),
280			Reported: cloneRaw(d.Reported),
281			LastSeq:  d.LastSeq,
282		}, nil
283	}
284	
285	// Diff 返回期望配置与上报配置之间的差异，按 JSON Pointer 路径字典序排列。
286	func (s *Store) Diff(deviceID string) ([]DiffEntry, error) {
287		s.mu.Lock()
288		defer s.mu.Unlock()
289		if err := s.checkOpen(); err != nil {
290			return nil, err
291		}
292		d, err := s.lookup(deviceID)
293		if err != nil {
294			return nil, err
295		}
296		entries := computeDiff(d.Desired, d.Reported)
297		for i := range entries {
298			entries[i].Since = d.DiffSince[entries[i].Path]
299		}
300		return entries, nil
301	}
302	
303	// Audit 按修订号递增返回设备的审计记录。返回的数据是独立副本。
304	func (s *Store) Audit(deviceID string) ([]AuditRecord, error) {
305		s.mu.Lock()
306		defer s.mu.Unlock()
307		if err := s.checkOpen(); err != nil {
308			return nil, err
309		}
310		d, err := s.lookup(deviceID)
311		if err != nil {
312			return nil, err
313		}
314		out := make([]AuditRecord, len(d.Audit))
315		for i, rec := range d.Audit {
316			out[i] = rec
317			out[i].Before = cloneRaw(rec.Before)
318			out[i].After = cloneRaw(rec.After)
319		}
320		return out, nil
321	}
322	
323	func (s *Store) checkOpen() error {
324		if s.closed {
325			return ErrClosed
326		}
327		return nil
328	}
329	
330	func (s *Store) lookup(deviceID string) (*deviceState, error) {
331		if deviceID == "" {
332			return nil, ErrInvalidDeviceID
333		}
334		d, ok := s.devices[deviceID]
335		if !ok {
336			return nil, fmt.Errorf("%w: %s", ErrDeviceNotFound, deviceID)
337		}
338		return d, nil
339	}
340	
341	// commit 执行一次状态修改并持久化。保存失败时回滚内存状态并返回错误，
342	// 保证一次操作涉及的状态与审计一起保存、查询仍显示操作前的结果。
343	// 调用时必须持有 s.mu。
344	func (s *Store) commit(mutate func() error) error {
345		snapshot, err := s.marshal()
346		if err != nil {
347			return err
348		}
349		if err := mutate(); err != nil {
350			return err
351		}
352		if err := s.persist(); err != nil {
353			// 回滚内存状态；snapshot 由本进程序列化，恢复不应失败。
354			_ = s.restore(snapshot)
355			return err
356		}
357		return nil
358	}
359	
360	func (s *Store) filePath() string {
361		return filepath.Join(s.dir, storeFileName)
362	}
363	
364	// persist 把当前状态原子写入存储文件。
365	func (s *Store) persist() error {
366		data, err := s.marshal()
367		if err != nil {
368			return err
369		}
370		tmp, err := os.CreateTemp(s.dir, ".shadow-store-*.tmp")
371		if err != nil {
372			return fmt.Errorf("shadow: save store: %w", err)
373		}
374		tmpName := tmp.Name()
375		if _, err := tmp.Write(data); err != nil {
376			tmp.Close()
377			os.Remove(tmpName)
378			return fmt.Errorf("shadow: save store: %w", err)
379		}
380		if err := tmp.Sync(); err != nil {
381			tmp.Close()
382			os.Remove(tmpName)
383			return fmt.Errorf("shadow: save store: %w", err)
384		}
385		if err := tmp.Close(); err != nil {
386			os.Remove(tmpName)
387			return fmt.Errorf("shadow: save store: %w", err)
388		}
389		if err := os.Rename(tmpName, s.filePath()); err != nil {
390			os.Remove(tmpName)
391			return fmt.Errorf("shadow: save store: %w", err)
392		}
393		return nil
394	}
395	
396	// diskStore 是存储文件的磁盘格式。
397	type diskStore struct {
398		Format    int                     `json:"format"`
399		Devices   map[string]diskState    `json:"devices"`
400		Versions  map[string]diskVersion  `json:"versions,omitempty"`
401		Campaigns map[string]diskCampaign `json:"campaigns,omitempty"`
402	}
403	
404	type diskState struct {
405		Version        string               `json:"version"`
406		Online         bool                 `json:"online"`
407		Revision       uint64               `json:"revision"`
408		Desired        json.RawMessage      `json:"desired"`
409		Reported       json.RawMessage      `json:"reported"`
410		LastSeq        uint64               `json:"lastSeq"`
411		LastReportTime time.Time            `json:"lastReportTime,omitempty"`
412		DiffSince      map[string]time.Time `json:"diffSince,omitempty"`
413		Audit          []diskAudit          `json:"audit,omitempty"`
414	}
415	
416	type diskAudit struct {
417		Operator string          `json:"operator"`
418		Time     time.Time       `json:"time"`
419		Revision uint64          `json:"revision"`
420		Before   json.RawMessage `json:"before"`
421		After    json.RawMessage `json:"after"`
422	}
423	
424	func (s *Store) marshal() ([]byte, error) {
425		disk := diskStore{Format: storeFormat, Devices: make(map[string]diskState, len(s.devices))}
426		for id, d := range s.devices {
427			ds := diskState{
428				Version:        d.Version,
429				Online:         d.Online,
430				Revision:       d.Revision,
431				Desired:        cloneRaw(d.Desired),
432				Reported:       cloneRaw(d.Reported),
433				LastSeq:        d.LastSeq,
434				LastReportTime: d.LastReportTime,
435				DiffSince:      make(map[string]time.Time, len(d.DiffSince)),
436			}
437			for p, t := range d.DiffSince {
438				ds.DiffSince[p] = t
439			}
440			for _, rec := range d.Audit {
441				ds.Audit = append(ds.Audit, diskAudit{
442					Operator: rec.Operator,
443					Time:     rec.Time,
444					Revision: rec.Revision,
445					Before:   cloneRaw(rec.Before),
446					After:    cloneRaw(rec.After),
447				})
448			}
449			disk.Devices[id] = ds
450		}
451		disk.Versions = s.marshalVersions()
452		campaigns, err := s.marshalCampaigns()
453		if err != nil {
454			return nil, err
455		}
456		disk.Campaigns = campaigns
457		data, err := json.Marshal(disk)
458		if err != nil {
459			return nil, fmt.Errorf("shadow: encode store: %w", err)
460		}
461		return data, nil
462	}
463	
464	// restore 从存储文件内容恢复状态。内容损坏或格式不识别时返回
465	// ErrCorruptStorage，绝不按空数据覆盖。
466	func (s *Store) restore(data []byte) error {
467		var disk diskStore
468		if err := json.Unmarshal(data, &disk); err != nil {
469			return fmt.Errorf("%w: %v", ErrCorruptStorage, err)
470		}
471		if disk.Format != storeFormat {
472			return fmt.Errorf("%w: unsupported format %d", ErrCorruptStorage, disk.Format)
473		}
474		devices := make(map[string]*deviceState, len(disk.Devices))
475		for id, ds := range disk.Devices {
476			if id == "" {
477				return fmt.Errorf("%w: empty device id", ErrCorruptStorage)
478			}
479			if _, ok := decodeObject(ds.Desired); !ok {
480				return fmt.Errorf("%w: device %s desired config invalid", ErrCorruptStorage, id)
481			}
482			if _, ok := decodeObject(ds.Reported); !ok {
483				return fmt.Errorf("%w: device %s reported config invalid", ErrCorruptStorage, id)
484			}
485			d := &deviceState{
486				Version:        ds.Version,
487				Online:         ds.Online,
488				Revision:       ds.Revision,
489				Desired:        cloneRaw(ds.Desired),
490				Reported:       cloneRaw(ds.Reported),
491				LastSeq:        ds.LastSeq,
492				LastReportTime: ds.LastReportTime,
493				DiffSince:      make(map[string]time.Time, len(ds.DiffSince)),
494			}
495			for p, t := range ds.DiffSince {
496				d.DiffSince[p] = t
497			}
498			var lastRev uint64
499			for _, da := range ds.Audit {
500				if da.Operator == "" || da.Time.IsZero() || da.Revision == 0 || da.Revision <= lastRev {
501					return fmt.Errorf("%w: device %s audit invalid", ErrCorruptStorage, id)
502				}
503				if _, ok := decodeObject(da.Before); !ok {
504					return fmt.Errorf("%w: device %s audit invalid", ErrCorruptStorage, id)
505				}
506				if _, ok := decodeObject(da.After); !ok {
507					return fmt.Errorf("%w: device %s audit invalid", ErrCorruptStorage, id)
508				}
509				lastRev = da.Revision
510				d.Audit = append(d.Audit, AuditRecord{
511					DeviceID: id,
512					Operator: da.Operator,
513					Time:     da.Time,
514					Revision: da.Revision,
515					Before:   cloneRaw(da.Before),
516					After:    cloneRaw(da.After),
517				})
518			}
519			devices[id] = d
520		}
521		s.devices = devices
522		if err := s.restoreVersions(disk.Versions); err != nil {
523			return err
524		}
525		if err := s.restoreCampaigns(disk.Campaigns); err != nil {
526			return err
527		}
528		return nil
529	}
